namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.Add(new Notification(_nextId++, "Welcome to the notification center!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new Notification(_nextId++, "Your profile was updated successfully.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new Notification(_nextId++, "New feature: dark mode is now available.", DateTime.UtcNow.AddMinutes(-2)));
    }

    /// <summary>
    /// Returns all notifications up to this point.
    /// </summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>
    /// Returns only notifications newer than the given timestamp.
    /// </summary>
    public List<Notification> GetSince(DateTime since)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Timestamp > since).ToList();
        }
    }

    /// <summary>
    /// Simulates new notifications arriving over time.
    /// Called internally to generate fake data on each poll.
    /// </summary>
    public void SimulateIncoming()
    {
        if (Random.Shared.NextDouble() < 0.4) // 40% chance each poll
        {
            lock (_lock)
            {
                var messages = new[]
                {
                    "You have a new follower!",
                    "Your build completed successfully.",
                    "Someone commented on your post.",
                    "Scheduled maintenance tonight at 11 PM.",
                    "Your subscription renews in 3 days.",
                    "A new version is available for download."
                };
                var msg = messages[Random.Shared.Next(messages.Length)];
                _notifications.Add(new Notification(_nextId++, msg, DateTime.UtcNow));
            }
        }
    }
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@using BlazorNotifications.Services
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@_notifications.Count</span></h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var notification in _notifications.OrderByDescending(n => n.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@notification.Message</span>
                <small class="text-muted">@notification.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        // Load initial notifications during prerender AND interactive init.
        // On the interactive init this reuses the same service state, so no extra fetch.
        _notifications = NotificationSvc.GetAll();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender only fires when the component is live and interactive
            // (never during static SSR prerender), so the polling loop starts only
            // once the page is truly interactive in the browser.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            if (ct.IsCancellationRequested)
                break;

            // Simulate new notifications arriving server-side
            NotificationSvc.SimulateIncoming();

            // Fetch latest
            var latest = NotificationSvc.GetAll();

            await InvokeAsync(() =>
            {
                _notifications = latest;
                StateHasChanged();
            });
        }
    }

    public void Dispose()
    {
        // Clean cancellation when the user navigates away — no leaked tasks.
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

